solution.solution.cpp:
#include <cstdint>
#include <cstring>
#include <vector>

using NTSTATUS = std::int32_t;
constexpr NTSTATUS STATUS_SUCCESS = 0;
constexpr NTSTATUS STATUS_INVALID_PARAMETER = static_cast<NTSTATUS>(0xC000000Du);
constexpr NTSTATUS STATUS_BUFFER_TOO_SMALL = static_cast<NTSTATUS>(0xC0000023u);

std::vector<std::uint8_t> buildReadRequest(std::uint64_t afterSeq)
{
    std::vector<std::uint8_t> b(16, 0);
    const std::uint32_t size{ 16 };
    std::memcpy(b.data(), &size, 4);
    std::memcpy(b.data() + 8, &afterSeq, 8);
    return b;
}

NTSTATUS validateReadRequest(const std::uint8_t* input, std::uint32_t inLength, std::uint32_t outLength, std::uint64_t& afterSeq)
{
    if (!input || inLength < 16 || outLength < 16) return STATUS_BUFFER_TOO_SMALL;
    std::uint32_t size, reserved;
    std::memcpy(&size, input, 4);
    std::memcpy(&reserved, input + 4, 4);
    if (size != 16 || reserved != 0) return STATUS_INVALID_PARAMETER;
    std::memcpy(&afterSeq, input + 8, 8);
    return STATUS_SUCCESS;
}

std::uint32_t recordsThatFit(std::uint32_t outLength)
{
    return outLength < 16 ? 0 : (outLength - 16) / 32;
}

unitTests:
TEST("round trip") {
    const auto req = buildReadRequest(0x0123456789ull); CHECK_EQ(req.size(), std::size_t{ 16 }); CHECK_EQ(int(req[0]), 16); CHECK_EQ(int(req[4]), 0);
    std::uint64_t after = 0; CHECK_EQ(validateReadRequest(req.data(), 16, 4096, after), STATUS_SUCCESS); CHECK_EQ(after, 0x0123456789ull);
}
TEST("bad requests") {
    std::uint64_t after = 7; auto req = buildReadRequest(5);
    CHECK_EQ(validateReadRequest(req.data(), 15, 4096, after), STATUS_BUFFER_TOO_SMALL); CHECK_EQ(validateReadRequest(req.data(), 16, 15, after), STATUS_BUFFER_TOO_SMALL);
    CHECK_EQ(validateReadRequest(nullptr, 16, 4096, after), STATUS_BUFFER_TOO_SMALL);
    req[4] = 1; CHECK_EQ(validateReadRequest(req.data(), 16, 4096, after), STATUS_INVALID_PARAMETER); req[4] = 0; req[0] = 24; CHECK_EQ(validateReadRequest(req.data(), 16, 4096, after), STATUS_INVALID_PARAMETER);
    CHECK_EQ(after, std::uint64_t{ 7 });
}
TEST("records that fit") { CHECK_EQ(recordsThatFit(16), 0u); CHECK_EQ(recordsThatFit(47), 0u); CHECK_EQ(recordsThatFit(48), 1u); CHECK_EQ(recordsThatFit(4096), 127u); CHECK_EQ(recordsThatFit(10), 0u); }

